```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=1365, initial-scale=1">
<meta name="sunny-upstream-hash" content="cc53e27067e7bc8a665907e6eb59b11ca421d10dad73430b8c4678caf2d6da08">
<title>Lantern Festival: The Night You Light</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
  html,body{height:100%;background:#05040d;overflow:hidden;font-family:"Trebuchet MS","Segoe UI",system-ui,sans-serif}
  #fit{position:fixed;inset:0;display:grid;place-items:center}
  #stage{
    position:relative;width:1365px;height:768px;overflow:hidden;
    --b1:#160f36;--b2:#2a1447;--b3:#0b0820;
    --gold:#ffcf6b;--amber:#e0913f;--teal:#57d4c8;--ink:#f6ecd8;--dark:#0a0718;
    background:radial-gradient(120% 90% at 50% 105%,var(--b2) 0%,var(--b1) 45%,var(--b3) 100%);
    color:var(--ink);user-select:none;border-radius:6px
  }
  #stage[data-pal="1"]{--b1:#0a2233;--b2:#0e3b4a;--b3:#04121c;--gold:#ffe08a;--amber:#d9a04a;--teal:#7fe6ff}
  #stage[data-pal="2"]{--b1:#241a3d;--b2:#3d2c5c;--b3:#100a1e;--gold:#fff0c4;--amber:#e0a86a;--teal:#bfe9ff}
  canvas{position:absolute;left:0;top:0;width:1365px;height:768px}
  #bg{z-index:0}
  #fx{z-index:60;pointer-events:none}
  .layer{position:absolute;z-index:10}

  /* ---------- canopy ---------- */
  #canopy{left:0;top:0;width:1365px;height:132px}
  #canopy svg{width:1365px;height:132px;display:block}
  .arcpath{fill:none;stroke:#241f4a;stroke-width:7;stroke-linecap:round;transition:stroke .6s ease}
  .arcpath.gold{stroke:var(--gold);filter:drop-shadow(0 0 10px rgba(255,207,107,.85))}
  .arcpath.amber{stroke:var(--amber);filter:drop-shadow(0 0 9px rgba(224,145,63,.7))}
  .arcbulb{fill:#1c1840;transition:fill .6s ease,filter .6s ease}
  .arcbulb.gold{fill:var(--gold);filter:drop-shadow(0 0 8px rgba(255,207,107,.9))}
  .arcbulb.amber{fill:var(--amber);filter:drop-shadow(0 0 7px rgba(224,145,63,.8))}
  .arcnum{fill:#7d76b5;font-size:13px;font-weight:bold;text-anchor:middle}
  .arcnum.on{fill:var(--ink)}
  #canopyLabel{position:absolute;left:18px;top:8px;font-size:13px;letter-spacing:.14em;color:#8d86c4}
  #palLabel{position:absolute;right:18px;top:8px;font-size:13px;letter-spacing:.1em;color:#8d86c4}

  /* ---------- text band ---------- */
  #beatTag{left:24px;top:136px;font-size:15px;color:var(--teal);letter-spacing:.06em;font-weight:bold}
  #stageTag{right:24px;top:136px;font-size:13px;color:#8d86c4}
  #story{left:190px;top:158px;width:985px;text-align:center;font-size:17px;line-height:1.35;color:#cfc6ef}
  #question{left:190px;top:184px;width:985px;text-align:center;font-size:25px;font-weight:bold;color:var(--ink);text-shadow:0 2px 10px rgba(0,0,0,.6)}

  /* ---------- scene ---------- */
  #scene{left:190px;top:216px;width:985px;height:220px;border-radius:16px;
    background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(0,0,0,.18));
    border:1px solid rgba(255,255,255,.07);overflow:hidden}
  .gwrap{position:absolute;inset:0;display:flex;flex-wrap:wrap;align-content:center;justify-content:center;gap:10px;padding:10px}
  .gcard{border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:6px 8px 8px;background:rgba(255,255,255,.05);
    display:flex;flex-direction:column;align-items:center;gap:4px;min-width:58px;transition:.25s}
  .gcard.ghost{border-style:dashed;background:rgba(255,255,255,.02)}
  .gcard.bin{border-color:rgba(255,207,107,.5);background:rgba(255,207,107,.07)}
  .glab{font-size:11px;color:#b9b0e0;letter-spacing:.04em;white-space:nowrap}
  .gitems{display:flex;flex-wrap:wrap;justify-content:center;gap:2px;max-width:190px}
  .it{line-height:1;filter:drop-shadow(0 0 5px rgba(255,190,110,.35))}
  .it.spill{color:#ff6a5c;transform:rotate(18deg);opacity:.85;filter:drop-shadow(0 0 6px rgba(255,80,60,.8))}
  .it.dim{opacity:.22;filter:none}
  .qmark{font-size:34px;font-weight:bold;color:var(--gold);text-shadow:0 0 14px rgba(255,207,107,.8);animation:breathe 2s infinite}
  @keyframes breathe{0%,100%{opacity:.55;transform:scale(.94)}50%{opacity:1;transform:scale(1.06)}}
  .pulseper .gitems{animation:pop .55s 2}
  .pulsegroup .glab{color:var(--gold);animation:pop .55s 2}
  @keyframes pop{0%,100%{transform:scale(1)}50%{transform:scale(1.16)}}
  .boardrow{display:flex;gap:6px;justify-content:center;margin:3px 0}

  /* tags (beat 1) */
  .tag{position:absolute;background:rgba(20,14,44,.92);border:2px solid rgba(255,207,107,.55);border-radius:14px;
    padding:7px 12px;font-size:15px;color:var(--ink);cursor:pointer;transition:.18s;box-shadow:0 0 16px rgba(255,207,107,.18)}
  .tag b{font-size:21px;color:var(--gold);margin-right:6px}
  .tag:hover{transform:translateY(-3px) scale(1.04);border-color:var(--gold)}
  .tag.off{pointer-events:none;opacity:.5}
  .tag.point{animation:pointto .8s infinite;border-color:var(--teal)}
  @keyframes pointto{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}

  #readout{left:190px;top:442px;width:985px;text-align:center;font-size:16px;color:#d7cdf3;height:22px}
  #readout .ok{color:#8ef2a5;font-weight:bold}
  #readout .bad{color:#ff8b7c;font-weight:bold}

  /* ---------- frame ---------- */
  #frame{left:190px;top:468px;width:985px;height:104px;display:flex;gap:14px}
  .slot{flex:1;position:relative;border:2px solid rgba(255,255,255,.15);background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(0,0,0,.25));
    border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:default;transition:.2s}
  .slot .sk{font-size:12px;letter-spacing:.16em;color:#a79ddd}
  .slot .sn{font-size:12px;color:#7d76b5;margin-top:1px}
  .slot .sv{font-size:34px;font-weight:bold;color:var(--ink);line-height:1.05;margin-top:2px;min-height:38px}
  .slot .ic{position:absolute;left:10px;top:8px;font-size:17px;opacity:.75}
  .slot.pick{cursor:pointer;border-color:rgba(255,207,107,.45)}
  .slot.pick:hover{transform:translateY(-3px);border-color:var(--gold);box-shadow:0 0 22px rgba(255,207,107,.3)}
  .slot.hole{border-style:dashed;border-color:rgba(255,207,107,.6);background:rgba(0,0,0,.45);animation:breathe 2s infinite}
  .slot.hole .sv{color:var(--gold)}
  .slot.named{border-color:var(--gold);box-shadow:0 0 24px rgba(255,207,107,.35) inset}
  .slot.shake{animation:shk .4s}
  @keyframes shk{0%,100%{transform:translateX(0)}25%{transform:translateX(-9px)}75%{transform:translateX(9px)}}
  .slot .flash{position:absolute;bottom:5px;font-size:12px;color:var(--gold);opacity:0}
  .slot.saying .flash{opacity:1;animation:fadeup 2.2s}
  @keyframes fadeup{0%{opacity:0}15%{opacity:1}80%{opacity:1}100%{opacity:0}}
  #frame[data-drag="1"] .slot.pick{border-color:var(--gold);box-shadow:0 0 18px rgba(255,207,107,.25)}

  /* ---------- controls ---------- */
  #controls{left:190px;top:584px;width:985px;height:150px;display:flex;gap:16px;align-items:stretch}
  .pane{flex:1;border-radius:14px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.04);padding:12px;position:relative}
  .paneTitle{font-size:13px;letter-spacing:.1em;color:#a79ddd;margin-bottom:8px}
  #ql{width:66px;height:78px;border-radius:12px 12px 18px 18px;background:radial-gradient(circle at 50% 35%,#fff2c8,#ffb43c 60%,#c96a12);
    display:flex;align-items:center;justify-content:center;font-size:33px;font-weight:bold;color:#4a2400;
    box-shadow:0 0 26px rgba(255,180,60,.7);cursor:grab;touch-action:none;position:relative;z-index:40}
  #ql.carry{cursor:grabbing;position:fixed;z-index:80;pointer-events:none;transform:translate(-33px,-40px)}
  .namerow{display:flex;align-items:center;gap:14px}
  .namehint{font-size:15px;color:#d7cdf3;line-height:1.35}
  .dialwrap{display:flex;flex-direction:column;gap:8px}
  .drow{display:flex;align-items:center;gap:12px}
  .dbtn{width:48px;height:48px;border-radius:12px;border:2px solid rgba(255,255,255,.2);background:rgba(255,255,255,.07);
    color:var(--ink);font-size:26px;cursor:pointer}
  .dbtn:hover{background:rgba(255,207,107,.2);border-color:var(--gold)}
  input[type=range]{-webkit-appearance:none;flex:1;height:14px;border-radius:9px;background:linear-gradient(90deg,#3a2f6b,#5b4aa0);outline:none}
  input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:34px;height:34px;border-radius:50%;
    background:radial-gradient(circle at 40% 35%,#fff3cc,#ffb43c);border:2px solid #7a4a09;cursor:pointer;box-shadow:0 0 14px rgba(255,180,60,.8)}
  input[type=range]::-moz-range-thumb{width:32px;height:32px;border-radius:50%;background:#ffb43c;border:2px solid #7a4a09;cursor:pointer}
  .dval{min-width:74px;text-align:center;font-size:34px;font-weight:bold;color:var(--gold)}
  .btn{border:2px solid var(--gold);border-radius:12px;background:linear-gradient(180deg,rgba(255,207,107,.28),rgba(255,207,107,.1));
    color:var(--ink);font-size:18px;font-weight:bold;padding:10px 18px;cursor:pointer;transition:.15s}
  .btn:hover{background:rgba(255,207,107,.42);transform:translateY(-2px)}
  .btn.sm{font-size:15px;padding:7px 13px}
  .btn[disabled]{opacity:.35;cursor:not-allowed;transform:none}
  #dialLock{position:absolute;inset:0;border-radius:14px;background:rgba(8,6,20,.82);display:flex;align-items:center;justify-content:center;
    text-align:center;font-size:15px;color:#c9bff0;padding:16px;cursor:pointer;z-index:5}
  #dialLock.shake{animation:shk .4s}
  .chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
  .chip{border:2px solid var(--gold);border-radius:20px;padding:5px 12px;font-size:16px;background:rgba(255,207,107,.14)}
  .chan{display:flex;gap:10px;align-items:center;margin-top:6px;font-size:13px;color:#b9b0e0}
  .led{width:16px;height:16px;border-radius:50%;background:#241f4a;border:1px solid rgba(255,255,255,.2)}
  .led.on{background:var(--gold);box-shadow:0 0 12px var(--gold)}
  .led.dead{animation:blink 1s infinite}
  @keyframes blink{0%,100%{opacity:1}50%{opacity:.25}}
  .opt{display:block;width:100%;text-align:left;margin-top:8px}

  /* ---------- npcs ---------- */
  .npc{width:150px;height:180px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;transition:.8s}
  #npcL{left:16px;top:250px}
  #npcR{left:1200px;top:250px}
  .npcface{font-size:52px;filter:drop-shadow(0 0 12px rgba(255,190,110,.4))}
  .npcname{font-size:12px;color:#8d86c4;margin-top:4px}
  .npc.back{opacity:.35;transform:scale(.8) translateY(26px)}
  #say{left:8px;top:150px;width:270px;background:rgba(12,9,28,.95);border:2px solid var(--teal);border-radius:14px;
    padding:11px 13px;font-size:15px;line-height:1.35;color:#e9e2ff;opacity:0;transition:.3s;z-index:50}
  #say.on{opacity:1}
  #ask{left:1150px;top:640px;z-index:40}
  #askNote{left:1120px;top:700px;width:230px;font-size:12px;color:#8d86c4;text-align:center}

  /* ---------- overlay ---------- */
  #overlay{position:absolute;inset:0;z-index:70;display:none;align-items:center;justify-content:center;
    background:radial-gradient(80% 80% at 50% 50%,rgba(10,7,24,.82),rgba(5,4,13,.96))}
  #overlay.on{display:flex}
  .card{max-width:1000px;text-align:center;padding:26px 34px}
  .big{font-size:42px;font-weight:bold;color:var(--gold);text-shadow:0 0 26px rgba(255,207,107,.5)}
  .mid{font-size:22px;margin-top:14px;line-height:1.45;color:#e9e2ff}
  .small{font-size:15px;color:#b9b0e0;margin-top:12px;line-height:1.5}
  .maprow{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:16px}
  .mapitem{border:1px solid rgba(255,255,255,.16);border-radius:10px;padding:7px 12px;font-size:14px;background:rgba(255,255,255,.05)}
  .mapitem .d{width:11px;height:11px;border-radius:50%;display:inline-block;margin-right:7px;vertical-align:middle}
  pre#crew{display:none;text-align:left;max-height:250px;overflow:auto;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.15);
    border-radius:10px;padding:12px;font-size:11px;line-height:1.35;color:#bfe9ff;margin-top:14px;white-space:pre-wrap}
  .toast{position:absolute;left:50%;top:96px;transform:translateX(-50%);z-index:65;background:rgba(12,9,28,.94);
    border:2px solid var(--gold);border-radius:14px;padding:9px 20px;font-size:19px;font-weight:bold;color:var(--gold);opacity:0;transition:.3s}
  .toast.on{opacity:1}
</style>
</head>
<body>
<div id="fit">
<div id="stage" data-pal="0">
  <canvas id="bg" width="1365" height="768"></canvas>

  <div class="layer" id="canopy">
    <svg id="canopySvg" viewBox="0 0 1365 132"></svg>
    <div id="canopyLabel">TONIGHT'S CANOPY</div>
    <div id="palLabel">DUSK</div>
  </div>

  <div class="layer" id="beatTag"></div>
  <div class="layer" id="stageTag"></div>
  <div class="layer" id="story"></div>
  <div class="layer" id="question"></div>
  <div class="layer" id="scene"></div>
  <div class="layer" id="readout"></div>

  <div class="layer" id="frame">
    <div class="slot" data-slot="groups"><div class="ic">▦</div><div class="sk">GROUPS</div><div class="sn"></div><div class="sv">—</div><div class="flash"></div></div>
    <div class="slot" data-slot="size"><div class="ic">🤲</div><div class="sk">SIZE OF EACH GROUP</div><div class="sn"></div><div class="sv">—</div><div class="flash"></div></div>
    <div class="slot" data-slot="total"><div class="ic">🪣</div><div class="sk">TOTAL</div><div class="sn"></div><div class="sv">—</div><div class="flash"></div></div>
  </div>

  <div class="layer" id="controls"></div>

  <div class="layer npc" id="npcL"><div class="npcface">🧑‍🔧</div><div class="npcname">Mira · rigging crew</div></div>
  <div class="layer npc" id="npcR"><div class="npcface">👩‍🎤</div><div class="npcname">Bo · booth crew</div></div>
  <div class="layer" id="say"></div>

  <button class="btn layer" id="ask">🙋 Ask a helper</button>
  <div class="layer" id="askNote"></div>

  <div class="toast" id="toast"></div>
  <canvas id="fx" width="1365" height="768"></canvas>

  <div id="overlay"><div class="card" id="ovcard"></div></div>
</div>
</div>

<script>
"use strict";
/* ============================================================
   Lantern Festival: The Night You Light
   Packet pkt-LAB-MATH-C-unknown-position-v1  (items lmc-c-01..07)
   Design exp-arch-LAB-MATH-C-lantern-festival-v1-juniper
   ============================================================ */

/* ---------------- fit ---------------- */
const stage=document.getElementById('stage');
function fit(){const s=Math.min(innerWidth/1365,innerHeight/768);stage.style.transform='scale('+s+')';stage.dataset.scale=s;}
addEventListener('resize',fit);fit();
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];

/* ---------------- canvas fx ---------------- */
const bg=$('#bg'),bx=bg.getContext('2d'),fx=$('#fx'),fc=fx.getContext('2d');
let parts=[],rings=[],sky=null,bgL=[];
for(let i=0;i<16;i++)bgL.push({x:Math.random()*1365,y:Math.random()*820,s:.12+Math.random()*.35,r:5+Math.random()*9,ph:Math.random()*6});
function lantern(ctx,x,y,r,col,a){
  ctx.save();ctx.globalAlpha=a;
  ctx.shadowColor=col;ctx.shadowBlur=r*2.2;ctx.fillStyle=col;
  ctx.beginPath();ctx.ellipse(x,y,r*.8,r,0,0,7);ctx.fill();
  ctx.shadowBlur=0;ctx.fillStyle='rgba(80,40,0,.55)';
  ctx.fillRect(x-r*.4,y-r*1.05,r*.8,r*.16);ctx.fillRect(x-r*.35,y+r*.9,r*.7,r*.16);
  ctx.restore();
}
function ring(x,y,col){rings.push({x,y,r:8,max:340,col});}
function rain(n,ch,x0,x1){for(let i=0;i<n;i++)parts.push({x:x0+Math.random()*(x1-x0),y:180+Math.random()*40,vx:(Math.random()-.5)*3,vy:1+Math.random()*3,ch,sz:16+Math.random()*10,rot:Math.random()*6,vr:(Math.random()-.5)*.3,life:1});}
function tick(t){
  bx.clearRect(0,0,1365,768);
  for(const l of bgL){l.y-=l.s;if(l.y<-40)l.y=810;lantern(bx,l.x+Math.sin(t/1400+l.ph)*11,l.y,l.r,'#ffb84d',.22);}
  fc.clearRect(0,0,1365,768);
  rings=rings.filter(r=>{r.r+=13;const a=1-r.r/r.max;if(a<=0)return false;
    fc.save();fc.globalAlpha=a*.7;fc.strokeStyle=r.col;fc.lineWidth=5;fc.shadowColor=r.col;fc.shadowBlur=22;
    fc.beginPath();fc.arc(r.x,r.y,r.r,0,7);fc.stroke();fc.restore();return true;});
  parts=parts.filter(p=>{p.vy+=.35;p.x+=p.vx;p.y+=p.vy;p.rot+=p.vr;p.life-=.008;
    if(p.y>800||p.life<=0)return false;
    fc.save();fc.globalAlpha=Math.max(0,p.life);fc.translate(p.x,p.y);fc.rotate(p.rot);
    fc.font=p.sz+'px serif';fc.textAlign='center';fc.fillText(p.ch,0,0);fc.restore();return true;});
  if(sky){for(const l of sky){l.x+=(l.tx-l.x)*.035;l.y+=(l.ty-l.y)*.035;
      lantern(fc,l.x+Math.sin(t/900+l.ph)*4,l.y,l.r,l.gold?'#ffd27a':'#e2913f',.95);}}
  requestAnimationFrame(tick);
}
requestAnimationFrame(tick);

/* ---------------- canopy ---------------- */
const svg=$('#canopySvg');
function buildCanopy(){
  svg.innerHTML='';
  for(let i=0;i<7;i++){
    const x0=30+i*192, x1=x0+172, cx=(x0+x1)/2;
    const p=document.createElementNS('http://www.w3.org/2000/svg','path');
    p.setAttribute('d',`M ${x0} 108 Q ${cx} 22 ${x1} 108`);p.setAttribute('class','arcpath');p.id='arc'+i;svg.appendChild(p);
    for(let k=1;k<=4;k++){const tt=k/5;
      const bxp=(1-tt)*(1-tt)*x0+2*(1-tt)*tt*cx+tt*tt*x1, byp=(1-tt)*(1-tt)*108+2*(1-tt)*tt*22+tt*tt*108;
      const c=document.createElementNS('http://www.w3.org/2000/svg','circle');
      c.setAttribute('cx',bxp);c.setAttribute('cy',byp+7);c.setAttribute('r',5.5);
      c.setAttribute('class','arcbulb');c.dataset.arc=i;svg.appendChild(c);}
    const tx=document.createElementNS('http://www.w3.org/2000/svg','text');
    tx.setAttribute('x',cx);tx.setAttribute('y',126);tx.setAttribute('class','arcnum');tx.id='arcn'+i;tx.textContent=i+1;svg.appendChild(tx);
  }
}
function lightArc(i,kind){
  $('#arc'+i).classList.add(kind);
  $$('.arcbulb').filter(c=>+c.dataset.arc===i).forEach((c,k)=>setTimeout(()=>c.classList.add(kind),k*110));
  $('#arcn'+i).classList.add('on');
}
buildCanopy();

/* ---------------- session record ---------------- */
const S={beat:-1,t:0,records:[],rec:null,pal:0,helpUsed:false,computedFirst:false,pairs24:[],nameStart:0,beatStart:0};

/* ---------------- helpers ---------------- */
function say(txt,ms=4200){const s=$('#say');s.textContent=txt;s.classList.add('on');clearTimeout(s._t);s._t=setTimeout(()=>s.classList.remove('on'),ms);}
function toast(txt,ms=1700){const e=$('#toast');e.textContent=txt;e.classList.add('on');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('on'),ms);}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;');}

/* ---------------- scene rendering ---------------- */
function glyphSize(n){return n>44?15:n>30?19:n>18?23:27;}
function renderScene(sp){
  const sc=$('#scene');
  let n=(typeof sp.groups==='number'&&typeof sp.per==='number')?sp.groups*sp.per:24;
  if(sp.bin!=null)n+=sp.bin;
  const fs=glyphSize(n);
  let h='<div class="gwrap">';
  const cap=(sp.cap==null)?Infinity:sp.cap;
  let count=0;
  if(sp.groups==='?'){
    for(let g=0;g<3;g++){h+='<div class="gcard ghost"><div class="glab">'+esc(sp.label)+' ?</div><div class="gitems">';
      for(let k=0;k<(typeof sp.per==='number'?sp.per:3);k++)h+='<span class="it dim" style="font-size:'+fs+'px">'+sp.glyph+'</span>';
      h+='</div></div>';}
    h+='<div class="gcard ghost"><div class="glab">how many?</div><div class="qmark">?</div></div>';
  }else{
    for(let g=0;g<sp.groups;g++){
      h+='<div class="gcard"><div class="glab">'+esc(sp.label)+' '+(g+1)+'</div><div class="gitems">';
      if(sp.per==='?'){h+='<div class="qmark">?</div>';}
      else{for(let k=0;k<sp.per;k++){count++;h+='<span class="it'+(count>cap?' spill':'')+'" style="font-size:'+fs+'px">'+sp.glyph+'</span>';}}
      h+='</div></div>';
    }
  }
  if(sp.bin!=null||sp.binUnknown){
    h+='<div class="gcard bin"><div class="glab">'+esc(sp.binLabel||'TOTAL bin')+'</div><div class="gitems">';
    if(sp.binUnknown)h+='<div class="qmark">?</div>';
    else for(let k=0;k<sp.bin;k++)h+='<span class="it" style="font-size:'+fs+'px">'+sp.glyph+'</span>';
    h+='</div></div>';
  }
  h+='</div>';
  sc.innerHTML=h;
}
function renderBoard(total,rows,glyph){
  const sc=$('#scene');
  if(rows<1||total%rows!==0){
    const per=Math.floor(total/rows),left=total-per*rows;
    let h='<div class="gwrap" style="flex-direction:column;gap:4px">';
    for(let r=0;r<rows&&r<10;r++){h+='<div class="boardrow">';for(let c=0;c<per;c++)h+='<span class="it" style="font-size:18px">'+glyph+'</span>';h+='</div>';}
    h+='<div class="boardrow">';for(let k=0;k<left;k++)h+='<span class="it spill" style="font-size:18px">'+glyph+'</span>';h+='</div></div>';
    sc.innerHTML=h;return;
  }
  const per=total/rows;let h='<div class="gwrap" style="flex-direction:column;gap:4px">';
  for(let r=0;r<rows;r++){h+='<div class="boardrow">';for(let c=0;c<per;c++)h+='<span class="it" style="font-size:'+(rows>9||per>12?14:19)+'px">'+glyph+'</span>';h+='</div>';}
  h+='</div>';sc.innerHTML=h;
}

/* ---------------- frame ---------------- */
let FR={names:{},vals:{},unknown:null,revealed:false,pickable:false};
function setFrame(names,known,unknown){
  FR={names:names||{},vals:Object.assign({groups:null,size:null,total:null},known||{}),unknown:unknown||null,revealed:false,pickable:false};
  paintFrame();
}
function paintFrame(){
  ['groups','size','total'].forEach(k=>{
    const el=document.querySelector('.slot[data-slot="'+k+'"]');
    el.classList.remove('pick','hole','named','saying');
    el.querySelector('.sn').textContent=FR.names[k]||'';
    let v='—';
    if(FR.revealed){ v = (k===FR.unknown)? '?' : (FR.vals[k]!=null? FR.vals[k] : '—'); }
    else { v = (FR.vals[k]!=null && FR.shownAlways) ? FR.vals[k] : '—'; }
    el.querySelector('.sv').textContent=v;
    if(FR.revealed&&k===FR.unknown)el.classList.add('hole');
    if(FR.pickable)el.classList.add('pick');
  });
}
function setSlotLive(k,val){const el=document.querySelector('.slot[data-slot="'+k+'"]');el.querySelector('.sv').textContent=val;}
function slotSay(k,msg){const el=document.querySelector('.slot[data-slot="'+k+'"]');el.querySelector('.flash').textContent=msg;
  el.classList.remove('saying');void el.offsetWidth;el.classList.add('saying');}

