/* ============================================================
   FLOW
   ============================================================ */
function startIntro(){
  const ov=$('#overlay');ov.classList.add('on');
  $('#ovcard').innerHTML='<div class="big">The Night You Light</div>'+
   '<div class="mid">“Tonight the whole festival goes dark unless someone can see what’s <b>MISSING</b>.<br>The crew says that’s you.”</div>'+
   '<div class="small">Seven stations. Each one is stuck because one quantity is unknown.<br>Name the hole, then dial the world until it fits.</div>'+
   '<div style="margin-top:22px"><button class="btn" id="go">Light the festival ▸</button></div>';
  $('#go').onclick=()=>{ov.classList.remove('on');nextBeat();};
}
function nextBeat(){
  S.beat++;
  if(S.beat>=BEATS.length){finale();return;}
  const b=BEATS[S.beat];
  S.t=0;S.helpUsed=false;S.computedFirst=false;S.beatStart=performance.now();
  S.rec={itemId:b.item,progressionStage:b.stg,assistance_level:'unassisted',error_type:null,
         name_latency_ms:[],parts:[],latency_ms:null};
  $('#beatTag').textContent='Beat '+b.n+' · '+b.station;
  $('#stageTag').textContent=b.stg;
  FR.shownAlways=!!b.shownAlways;
  setFrame(b.names,b.known,null);FR.shownAlways=!!b.shownAlways;paintFrame();
  $('#npcL').classList.toggle('back',b.help===null);
  $('#npcR').classList.toggle('back',b.help===null);
  $('#ask').style.display=b.help?'block':'none';
  $('#askNote').textContent=b.help?'One helper prompt per station. It is recorded honestly.':'No prompts here. Helpers at the fence.';
  $('#ask').disabled=false;$('#ask').textContent='🙋 Ask a helper';
  runTask();
}
function advance(){S.t++;const b=BEATS[S.beat];if(S.t>=b.tasks.length)completeBeat();else runTask();}
function completeBeat(){
  const b=BEATS[S.beat];
  S.rec.latency_ms=Math.round(performance.now()-S.beatStart);
  S.records.push(S.rec);
  const kind=S.rec.assistance_level==='unassisted'?'gold':'amber';
  lightArc(S.beat,kind);ring(682,326,kind==='gold'?'#ffcf6b':'#e0913f');
  toast(kind==='gold'?'Arc '+b.n+' burns GOLD ✦':'Arc '+b.n+' glows AMBER — still lit, still counted');
  $('#controls').innerHTML='';$('#readout').innerHTML='';
  setTimeout(nextBeat,1500);
}
function curTask(){return BEATS[S.beat].tasks[S.t];}

/* ---------------- task router ---------------- */
function runTask(){
  const b=BEATS[S.beat],t=curTask();
  $('#story').textContent=t.story||b.story;
  $('#question').innerHTML=esc(t.q);
  if(t.names||t.known){FR.shownAlways=!!b.shownAlways;setFrame(t.names||b.names,t.known||b.known,null);FR.shownAlways=!!b.shownAlways;paintFrame();}
  if(t.type==='tags')taskTags(t);
  else if(t.type==='name')taskName(t);
  else if(t.type==='dial')taskDial(t);
  else if(t.type==='pairs')taskPairs(t);
  else if(t.type==='statement')taskStatement(t);
}

/* ---------------- BEAT 1 : tag tap ---------------- */
function taskTags(t){
  renderScene(t.scene);
  const sc=$('#scene');
  t.opts.forEach((o,i)=>{
    const d=document.createElement('div');
    d.className='tag off';d.style.left=o.x+'px';d.style.top=o.y+'px';
    d.innerHTML='<b>'+o.n+'</b>'+esc(o.s);d.dataset.i=i;sc.appendChild(d);
  });
  $('#controls').innerHTML='<div class="pane"><div class="paneTitle">HOW THIS WORKS</div>'+
    '<div class="namehint">Tapping a tag makes the world show you what that number really <b>is</b>.<br>Watch Mira try one…</div></div>'+
    '<div class="pane"><div class="paneTitle">NUMBERS COME LATER</div><div class="namehint">Nothing to compute at this booth. Just point at the right lantern tag.</div></div>';
  const tags=[...sc.querySelectorAll('.tag')];
  // demonstration: helper taps the "6" tag
  setTimeout(()=>{tags[0].classList.add('point');say('Watch: I tap the 6.');},500);
  setTimeout(()=>{tags[0].classList.remove('point');sc.querySelectorAll('.gcard').forEach(c=>c.classList.add('pulsegroup'));
    say('See? This one is the NUMBER OF GROUPS, because it counts helpers.',3800);},1900);
  setTimeout(()=>{
    sc.querySelectorAll('.gcard').forEach(c=>c.classList.remove('pulsegroup'));
    FR.revealed=false;setSlotLive('groups',6);
    tags.forEach(x=>x.classList.remove('off'));
    S.nameStart=performance.now();
    say('Now you. Which of these is the SIZE OF EACH GROUP?',5000);
  },4200);
  tags.forEach(el=>el.onclick=()=>{
    const i=+el.dataset.i;const ms=Math.round(performance.now()-S.nameStart);
    if(i===t.correct){
      S.rec.name_latency_ms.push(ms);S.rec.correct=(S.rec.attempted?false:true);
      sc.querySelectorAll('.gcard').forEach(c=>c.classList.add('pulseper'));
      setSlotLive('size',5);ring(682,326,'#ffcf6b');
      say('That’s it — 5 is what ONE helper carries. Size of each group.',3200);
      tags.forEach(x=>x.classList.add('off'));
      $('#readout').innerHTML='<span class="ok">6 helpers × 5 lanterns each = 30 lanterns. All three named.</span>';
      setTimeout(advance,2000);
    }else{
      S.rec.attempted=true;S.rec.correct=false;
      if(i===0){sc.querySelectorAll('.gcard').forEach(c=>c.classList.add('pulsegroup'));say('That counts the HELPERS — that’s the number of groups, not the size of each one.');
        setTimeout(()=>sc.querySelectorAll('.gcard').forEach(c=>c.classList.remove('pulsegroup')),1400);}
      else if(i===2){sc.querySelectorAll('.gcard').forEach(c=>c.classList.add('pulseper'));say('30 is every lantern together — that’s the TOTAL.');
        setTimeout(()=>sc.querySelectorAll('.gcard').forEach(c=>c.classList.remove('pulseper')),1400);}
      else{say('There is a group size here — look at one helper’s arms.');}
      el.classList.add('off');setTimeout(()=>el.classList.remove('off'),1200);
    }
  });
}

/* ---------------- NAME step (question-lantern onto the dark slot) ---------------- */
function taskName(t){
  renderScene(t.scene);
  FR.revealed=false;FR.pickable=true;paintFrame();
  $('#controls').innerHTML=
   '<div class="pane"><div class="paneTitle">STEP 1 · NAME</div><div class="namerow">'+
   '<div id="ql">?</div><div class="namehint">Drop the <b>question-lantern</b> on the slot that is <b>dark</b> — the quantity nobody has told you.<br><span style="color:#8d86c4">(You can also just tap a slot.)</span></div>'+
   '</div></div>'+
   '<div class="pane"><div class="paneTitle">STEP 2 · ACT</div><div class="dialwrap">'+
   '<div class="drow"><button class="dbtn">−</button><input type="range" min="1" max="12" value="1"><div class="dval">1</div><button class="dbtn">+</button></div>'+
   '</div><div id="dialLock">🔒 '+esc(t.lock||'The station will not take numbers until you name what is missing.')+'</div></div>';
  $('#dialLock').onclick=()=>{S.computedFirst=true;$('#dialLock').classList.remove('shake');void $('#dialLock').offsetWidth;$('#dialLock').classList.add('shake');
    say('Numbers are locked. Name the hole first — that’s the whole trick tonight.');};
  S.nameStart=performance.now();
  setupDrag();
  $$('.slot').forEach(el=>el.onclick=()=>{if(FR.pickable)pickSlot(el.dataset.slot,t);});
}
let dragging=false;
function setupDrag(){
  const ql=$('#ql');if(!ql)return;
  ql.onpointerdown=e=>{
    e.preventDefault();dragging=true;ql.classList.add('carry');
    const mv=ev=>{ql.style.left=ev.clientX+'px';ql.style.top=ev.clientY+'px';};
    const up=ev=>{
      dragging=false;ql.classList.remove('carry');ql.style.left='';ql.style.top='';
      document.removeEventListener('pointermove',mv);document.removeEventListener('pointerup',up);
      $('#frame').dataset.drag='0';
      const el=document.elementFromPoint(ev.clientX,ev.clientY);
      const slot=el&&el.closest?el.closest('.slot'):null;
      if(slot&&FR.pickable)pickSlot(slot.dataset.slot,curTask());
    };
    mv(e);$('#frame').dataset.drag='1';
    document.addEventListener('pointermove',mv);document.addEventListener('pointerup',up);
  };
}
function pickSlot(k,t){
  if(!FR.pickable)return;
  const ms=Math.round(performance.now()-S.nameStart);
  const totalKnown=FR.vals.total!=null;
  if(k===t.correct){
    S.rec.name_latency_ms.push(ms);
    if(S.rec.namedCorrectFirst===undefined)S.rec.namedCorrectFirst=!S.rec.nameMissed;
    S.rec.unknown_named_before_computing=!S.computedFirst;
    FR.pickable=false;FR.revealed=true;FR.unknown=k;paintFrame();
    document.querySelector('.slot[data-slot="'+k+'"]').classList.add('named');
    ring(682,520,'#ffcf6b');
    say('Click. The station knows its job now.',2200);
    const nxt=BEATS[S.beat].tasks[S.t+1];
    if(!nxt||nxt.type!=='dial'){
      $('#readout').innerHTML='<span class="ok">Named it — no number needed here. You found the hole.</span>';
      setTimeout(advance,1500);
    }else{setTimeout(advance,900);}
  }else{
    S.rec.nameMissed=true;
    const err=(k==='total'&&totalKnown)?'multiply_the_given_numbers':(t.correct==='total'?'divide_when_total_unknown':'other');
    if(!S.rec.error_type)S.rec.error_type=err;
    reactNameError(err,k,t);
  }
}
function reactNameError(err,k,t){
  const el=document.querySelector('.slot[data-slot="'+k+'"]');
  el.classList.remove('shake');void el.offsetWidth;el.classList.add('shake');
  if(err==='multiply_the_given_numbers'){
    const a=FR.vals.groups,b=FR.vals.size,prod=a*b,cap=FR.vals.total;
    slotSay('total','I never moved — '+cap+' is '+cap+'.');
    rain(34,t.scene.glyph,260,1100);
    say('If we multiply the two we can SEE, we’d need '+prod+' — on a rig built for '+cap+'! The total isn’t missing.',5200);
    $('#readout').innerHTML='<span class="bad">'+a+' × '+b+' = '+prod+' … but the total is fixed at '+cap+'. Something else is the hole.</span>';
  }else if(err==='divide_when_total_unknown'){
    const sp=Object.assign({},t.scene);sp.per=Math.max(1,Math.floor((sp.per||4)/2));
    renderScene(sp);
    say('Half-empty! Nothing exists to share out yet — the TOTAL is the thing we don’t know.',5000);
    $('#readout').innerHTML='<span class="bad">There is no total to split here. Both factors are already on the order sheet.</span>';
    setTimeout(()=>renderScene(t.scene),1500);
  }else{
    slotSay(k,'Already known: '+FR.vals[k]);
    say('That one already has its number — the story told you that part.',3000);
  }
}

/* ---------------- DIAL step ---------------- */
function taskDial(t){
  FR.revealed=true;FR.pickable=false;
  FR.unknown=(t.role==='total')?'total':(t.role==='groups'?'groups':'size');
  paintFrame();
  let val=t.min;
  $('#controls').innerHTML=
   '<div class="pane" style="flex:0 0 300px"><div class="paneTitle">STEP 1 · NAMED ✓</div>'+
   '<div class="namerow"><div id="ql" style="cursor:default;box-shadow:0 0 34px rgba(255,180,60,.9)">?</div>'+
   '<div class="namehint">You named the hole:<br><b>'+esc(FR.names[FR.unknown])+'</b><br>The station is unlocked.</div></div></div>'+
   '<div class="pane"><div class="paneTitle">STEP 2 · ACT — dial the world until it fits</div><div class="dialwrap">'+
   '<div class="drow"><button class="dbtn" id="dm">−</button><input type="range" id="dr" min="'+t.min+'" max="'+t.max+'" value="'+t.min+'"><div class="dval" id="dv">'+t.min+'</div><button class="dbtn" id="dp">+</button></div>'+
   '<div><button class="btn" id="dc">Set it ▸</button></div></div></div>';
  const dr=$('#dr');
  const paint=()=>{
    $('#dv').textContent=val;dr.value=val;setSlotLive(FR.unknown,val);
    let sp;
    if(t.role==='groups')sp={glyph:t.glyph,groups:val,per:t.per,label:t.label,cap:t.total};
    else if(t.role==='per')sp={glyph:t.glyph,groups:t.groups,per:val,label:t.label,cap:t.total};
    else sp={glyph:t.glyph,groups:t.groups,per:t.per,label:t.label,bin:val,binLabel:'TOTAL bin'};
    renderScene(sp);
    if(t.role==='total'){
      $('#readout').innerHTML='Your bin: <b>'+val+' '+t.ui+'</b>. The '+t.groups+' '+t.ug+' hold '+t.groups+' × '+t.per+' each — does the bin match?';
    }else{
      const g=(t.role==='groups')?val:t.groups, p=(t.role==='groups')?t.per:val, u=g*p;
      $('#readout').innerHTML=g+' '+t.ug+' × '+p+' '+t.ui+' = <b>'+u+'</b> of '+t.total+' '+t.ui+
        (u===t.total?' <span class="ok">✓ perfect fit</span>':u>t.total?' <span class="bad">— '+(u-t.total)+' too many!</span>':' <span class="bad">— '+(t.total-u)+' left over</span>');
    }
  };
  paint();
  dr.oninput=()=>{val=+dr.value;paint();};
  $('#dm').onclick=()=>{val=Math.max(t.min,val-1);paint();};
  $('#dp').onclick=()=>{val=Math.min(t.max,val+1);paint();};
  const start=performance.now();
  $('#dc').onclick=()=>{
    if(val===t.correct){
      if(S.rec.dialMissed===undefined)S.rec.dialCorrectFirst=true;
      S.rec.parts.push({role:t.role,answer:val,correct:true,first_try:!S.rec.dialMissed,ms:Math.round(performance.now()-start)});
      ring(682,326,'#ffcf6b');
      $('#scene').querySelectorAll('.gcard').forEach((c,i)=>setTimeout(()=>c.classList.add('pulseper'),i*45));
      say(t.role==='total'?'Bin full and correct. The booth is stocked.':'It fits. Every group equal, nothing left over.',2600);
      setTimeout(advance,1500);
    }else{
      S.rec.dialMissed=true;
      const e=(Math.abs(val-t.correct)===1)?'computation_slip':'other';
      if(!S.rec.error_type)S.rec.error_type=e;
      if(t.role==='total'){
        if(val<t.correct){say('The crates hold more than that — cups left standing on the counter.');}
        else{say('Too many cups for '+t.groups+' crates of '+t.per+'. The bin overflows.');rain(10,t.glyph,500,900);}
      }else{
        const g=(t.role==='groups')?val:t.groups,p=(t.role==='groups')?t.per:val,u=g*p;
        if(u>t.total){rain(Math.min(24,u-t.total),t.glyph,300,1050);say('Overshoot! The '+t.ui+' spill — the total can’t stretch past '+t.total+'.');}
        else{say('Not enough yet — '+(t.total-u)+' '+t.ui+' still waiting. Nudge the dial.');}
      }
      const w=$('#scene');w.style.transform='translateX(6px)';setTimeout(()=>w.style.transform='',160);
    }
  };
}

/* ---------------- PAIRS (factor pairs for a known total) ---------------- */
let nudgeTimer=null;
function taskPairs(t){
  FR.shownAlways=true;FR.revealed=false;FR.pickable=false;
  FR.vals={groups:null,size:null,total:t.total};paintFrame();setSlotLive('total',t.total);
  let rows=1,found=[],nudged=false;
  $('#controls').innerHTML=
   '<div class="pane"><div class="paneTitle">PROGRAM THE BOARD — equal rows only</div><div class="dialwrap">'+
   '<div class="drow"><button class="dbtn" id="dm">−</button><input type="range" id="dr" min="1" max="'+t.total+'" value="1"><div class="dval" id="dv">1</div><button class="dbtn" id="dp">+</button></div>'+
   '<div style="display:flex;gap:10px"><button class="btn sm" id="add">Send this arrangement up ▸</button>'+
   '<button class="btn sm" id="prog" disabled>'+(t.total===36?'Program the show ▸':'Raise the arch ▸')+'</button></div>'+
   '</div></div>'+
   '<div class="pane" style="flex:0 0 330px"><div class="paneTitle">ARRANGEMENTS SENT</div><div class="chips" id="chips"></div>'+
   '<div class="chan"><span class="led" id="l1"></span>channel 1 <span class="led dead" id="l2"></span>channel 2</div>'+
   '<div class="namehint" id="chanmsg" style="font-size:13px;margin-top:6px;color:#8d86c4">The board runs on two channels. One layout will not light it.</div></div>';
  const paint=()=>{
    $('#dv').textContent=rows;$('#dr').value=rows;
    renderBoard(t.total,rows,t.glyph);
    setSlotLive('groups',rows);
    if(t.total%rows===0){const per=t.total/rows;setSlotLive('size',per);
      $('#readout').innerHTML=rows+' rows × '+per+' in each row = <b>'+t.total+'</b> <span class="ok">✓ equal rows</span>';}
    else{const per=Math.floor(t.total/rows),left=t.total-per*rows;setSlotLive('size','?');
      $('#readout').innerHTML=rows+' rows … <span class="bad">'+left+' left over — the rows are not equal</span>';}
  };
  paint();
  $('#dr').oninput=()=>{rows=+$('#dr').value;paint();};
  $('#dm').onclick=()=>{rows=Math.max(1,rows-1);paint();};
  $('#dp').onclick=()=>{rows=Math.min(t.total,rows+1);paint();};
  $('#add').onclick=()=>{
    if(t.total%rows!==0){
      if(!S.rec.error_type)S.rec.error_type='invalid_pair';
      say('Those rows are not equal — the leftovers have nowhere to sit.');
      rain(6,t.glyph,560,820);return;
    }
    if(found.some(f=>f[0]===rows)){say('You already sent that one up. Find a DIFFERENT way.');return;}
    found.push([rows,t.total/rows]);
    if(found.length===1){
      $('#l1').classList.add('on');
      $('#chanmsg').textContent='Channel 2 is still dark. The show cannot run on one arrangement.';
      clearTimeout(nudgeTimer);
      if(BEATS[S.beat].help){
        nudgeTimer=setTimeout(()=>{
          if(found.length<2){nudged=true;S.rec.assistance_level='prompted_keep_going';
            say('Keep going — the board wants another way. If 4 rows worked, what about 6? Or 9?',6000);}
        },18000);
      }
    }
    if(found.length===2){
      $('#l2').classList.add('on');$('#l2').classList.remove('dead');
      $('#chanmsg').textContent='Both channels alive. The board is alternating your two layouts overhead.';
      S.rec.second_pair_unprompted=!nudged;
      say('Two different ways — the board runs them both. More than one is TRUE.',4200);
      clearTimeout(nudgeTimer);
    }
    ring(682,326,'#ffcf6b');
    $('#chips').innerHTML=found.map(f=>'<div class="chip">'+f[0]+' × '+f[1]+'</div>').join('');
    $('#prog').disabled=found.length<t.min;
  };
  $('#prog').onclick=()=>{
    if(found.length<t.min){
      if(!S.rec.error_type)S.rec.error_type='stopping_early';
      say('Channel 2 stays dead. One arrangement is not enough.');return;}
    S.rec.distinct_valid_pair_count=found.length;
    S.rec.factorPairs=found.map(f=>f[0]+' x '+f[1]);
    if(S.rec.second_pair_unprompted===undefined)S.rec.second_pair_unprompted=!nudged;
    if(t.store24)S.pairs24=found.slice();
    clearTimeout(nudgeTimer);
    advance();
  };
}

/* ---------------- STATEMENT ---------------- */
function taskStatement(t){
  $('#controls').innerHTML='<div class="pane"><div class="paneTitle">FINISH THE SENTENCE</div>'+
    '<div class="namehint">“For 36 lights there is <b>___</b> correct arrangement.”</div>'+
    t.opts.map((o,i)=>'<button class="btn sm opt" data-i="'+i+'">'+esc(o)+'</button>').join('')+'</div>'+
    '<div class="pane" style="flex:0 0 330px"><div class="paneTitle">THE BOARD SAYS</div>'+
    '<div class="namehint">'+ (S.rec.factorPairs||[]).map(p=>'✦ '+p).join('<br>') +'</div></div>';
  $$('#controls .opt').forEach(b=>b.onclick=()=>{
    const i=+b.dataset.i;
    if(i===t.correct){S.rec.multiplicityStatement='more than one';say('Right. A known total can be built more than one way.',3000);
      ring(682,326,'#ffcf6b');setTimeout(advance,1200);}
    else{if(!S.rec.error_type)S.rec.error_type='other';
      say('But you just built it two different ways yourself — look at the chips.');b.disabled=true;}
  });
}

/* ---------------- help button ---------------- */
$('#ask').onclick=()=>{
  const b=BEATS[S.beat];if(!b.help||S.helpUsed)return;
  S.helpUsed=true;$('#ask').disabled=true;$('#ask').textContent='helper used ✓';
  const t=curTask();
  S.rec.assistance_level = b.help==='prompted_keep_going' ? 'prompted_keep_going' : b.help;
  const h=t.hint|| (b.tasks.find(x=>x.hint)||{}).hint ||'Say which quantity is missing before you touch a number.';
  say(h,7000);
  if(t.type==='tags'){const tg=$('#scene').querySelectorAll('.tag')[t.correct];if(tg)tg.classList.add('point');}
  if(t.type==='name'){const el=document.querySelector('.slot[data-slot="'+t.correct+'"]');if(el)el.classList.add('hole');}
};

/* ---------------- FINALE ---------------- */
function finale(){
  const gold=S.records.filter(r=>r.assistance_level==='unassisted').length;
  const ov=$('#overlay');ov.classList.add('on');
  const pairs=S.pairs24.length?S.pairs24:[[4,6],[3,8]];
  $('#ovcard').innerHTML='<div class="big">Closing night.</div>'+
    '<div class="mid">Every arc you lit is ready to rise.<br>You choose tonight’s sky — from the arrangements of <b>24</b> you found yourself.</div>'+
    '<div class="maprow" id="skypick">'+pairs.map((p,i)=>'<button class="btn" data-i="'+i+'">'+p[0]+' rows of '+p[1]+'</button>').join('')+'</div>';
  $$('#skypick .btn').forEach(b=>b.onclick=()=>{
    const p=pairs[+b.dataset.i];ov.classList.remove('on');launchSky(p[0],p[1],gold);
  });
}
function launchSky(rows,cols,goldArcs){
  $('#story').textContent='';$('#question').textContent='The lantern release.';
  $('#scene').innerHTML='';$('#readout').textContent='';$('#controls').innerHTML='';
  $('#ask').style.display='none';$('#askNote').textContent='';
  $('#npcL').classList.add('back');$('#npcR').classList.add('back');
  const total=rows*cols,goldN=Math.round(total*goldArcs/7);
  const gapX=Math.min(64,900/Math.max(1,cols-1||1)),gapY=Math.min(56,340/Math.max(1,rows-1||1));
  const w=(cols-1)*gapX,h=(rows-1)*gapY,cx=682,top=250-h/2+60;
  sky=[];let idx=0;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    sky.push({x:200+Math.random()*965,y:820+Math.random()*260,tx:cx-w/2+c*gapX,ty:top+r*gapY,
      r:15,gold:idx<goldN,ph:Math.random()*6});idx++;}
  for(let i=0;i<7;i++)ring(682,400,'#ffcf6b');
  toast('✦ '+rows+' rows of '+cols+' — your sky ✦',3000);
  setTimeout(()=>plaque(goldArcs),4200);
}
function plaque(goldArcs){
  const ov=$('#overlay');ov.classList.add('on');
  const map=S.records.map((r,i)=>{
    const g=r.assistance_level==='unassisted';
    return '<div class="mapitem"><span class="d" style="background:'+(g?'#ffcf6b':'#e0913f')+'"></span>Beat '+(i+1)+' · '+BEATS[i].station+' — '+(g?'gold':'amber ('+r.assistance_level+')')+'</div>';
  }).join('');
  const lat=S.records.map((r,i)=>r.name_latency_ms.length?('B'+(i+1)+': '+Math.round(r.name_latency_ms.reduce((a,b)=>a+b,0)/r.name_latency_ms.length)+'ms'):null).filter(Boolean).join(' · ');
  $('#ovcard').innerHTML='<div class="big">You lit seven stations by finding what was missing<br>before anyone else could see it.</div>'+
   '<div class="mid">'+goldArcs+' of 7 arcs burned gold — solved with nobody helping.</div>'+
   '<div class="small">Tonight’s map, not a grade:</div><div class="maprow">'+map+'</div>'+
   '<div class="small">Time to NAME the unknown, station by station: '+esc(lat||'—')+'</div>'+
   '<div style="margin-top:18px;display:flex;gap:12px;justify-content:center">'+
   '<button class="btn" id="again">Run it again — new night ▸</button>'+
   '<button class="btn sm" id="crewbtn">For the crew ▾</button></div>'+
   '<pre id="crew"></pre>';
  $('#crew').textContent=JSON.stringify({packetId:'pkt-LAB-MATH-C-unknown-position-v1',
    assignmentId:'LAB-MATH-C',records:S.records},null,1);
  $('#crewbtn').onclick=()=>{const c=$('#crew');c.style.display=c.style.display==='block'?'none':'block';};
  $('#again').onclick=()=>{
    S.pal=(S.pal+1)%3;stage.dataset.pal=S.pal;
    $('#palLabel').textContent=['DUSK','RAIN-GLOW','SNOW FESTIVAL'][S.pal];
    S.records=[];S.beat=-1;S.pairs24=[];sky=null;parts=[];rings=[];
    buildCanopy();$('#overlay').classList.remove('on');
    $('#npcL').classList.remove('back');$('#npcR').classList.remove('back');
    $('#ask').style.display='block';
    say('Same seven stations, a different sky. Turn those amber arcs gold.',5000);
    nextBeat();
  };
}

/* ---------------- opening beat: first three seconds ---------------- */
$('#story').textContent='';
$('#question').textContent='';
setTimeout(()=>say('Six helpers turn toward you. The lanterns wake up one by one…',3200),300);
startIntro();
</script>
</body>
</html>
```

**Notes on the polish that matters here (Rowan):**

- **The gate is mechanical, not moral.** Every station shows a locked dial (🔒) during the NAME step. Tapping it doesn't scold — it shakes, says "numbers are locked," and quietly records `unknown_named_before_computing: false`. That's dec-002 as machinery, exactly as `xd-001` specifies.
- **Errors are world events, coded distinctly.** Naming TOTAL when the total is given rains the *product* down the screen and the TOTAL bin flashes *"I never moved — 48 is 48"* (`multiply_the_given_numbers`). Naming a factor at Beat 5A's juice booth half-empties the crates (`divide_when_total_unknown`). Over/under-dialing spills or leaves leftovers; off-by-one is coded `computation_slip`. No buzzer, no red X, no scoreboard drop.
- **One gesture grammar.** Tag-tap → drop-on-hole → drop-then-dial → two cycles interleaved → dial twice against a fixed total → all of it unassisted. Nothing new to learn after Beat 3.
- **Honest gold/amber.** Assistance is one press per station, recorded as `prompted` / `modeled` / `prompted_keep_going`, and the arc colour follows the record, never the outcome. The Beat 6 keep-going nudge only fires after 18s of stall, so `second_pair_unprompted` stays truthful.
- **The finale is the child's own answer.** The sky array is built from a factor pair *they* found for 24, with gold/amber lanterns in the proportion actually earned.
- No storage, no Sunny APIs, no speech synthesis, no oscillators; every sound cue was replaced by a visual twin, so the experience is fully legible muted.
- Inherited honesty, unchanged: this packet embeds naming in every item, so nothing here can separate naming from practice. The NAME-step latency is logged per beat and surfaced on the closing plaque so the naming-adds-cost check is at least measurable.
